// IDs are generated by the server; restrict them to single, literal path components.
function validOwnerIds(memoryId?: string, photoId?: string): boolean {
  return !!memoryId && !!photoId &&
    /^[a-zA-Z0-9-]+$/.test(memoryId) && /^[a-zA-Z0-9-]+$/.test(photoId);
}

export function isOwnedOciPhotoKey(key: string, memoryId?: string, photoId?: string): boolean {
  if (!validOwnerIds(memoryId, photoId)) return false;
  const prefix = `memories/${memoryId}/photos/${photoId}/`;
  return key.startsWith(prefix) && /^image_\d+\.(jpg|png|webp|gif)$/.test(key.slice(prefix.length));
}

export function isOwnedLocalPhotoFile(file: string, memoryId?: string, photoId?: string): boolean {
  if (!validOwnerIds(memoryId, photoId)) return false;
  const prefix = `${memoryId}_${photoId}_`;
  return file.startsWith(prefix) && /^\d+\.(jpg|png|webp|gif)$/.test(file.slice(prefix.length));
}
